import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.apache.commons.text.StringSubstitutor;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Pattern;

@WebServlet("/api/reports")
public class ReportGeneratorServlet extends HttpServlet {

    private static final Pattern SAFE_IDENTIFIER = Pattern.compile("^[a-zA-Z][a-zA-Z0-9_]{0,63}$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String sortColumn = req.getParameter("sort");
        String filterDate = req.getParameter("from_date");
        String customerId = req.getParameter("customer_id");

        if (reportType == null || sortColumn == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate sort column against allowlist pattern
        if (!SAFE_IDENTIFIER.matcher(sortColumn).matches()) {
            resp.sendError(400, "Invalid sort column");
            return;
        }

        // Template-based query construction
        Map<String, String> templateVars = new HashMap<>();
        templateVars.put("sort_col", sortColumn);
        templateVars.put("report_type", reportType);

        String queryTemplate;
        if ("summary".equals(reportType)) {
            queryTemplate = "SELECT id, name, total FROM reports WHERE type='summary' "
                + "AND created_at >= '" + filterDate + "' "
                + "ORDER BY ${sort_col} ASC";
        } else if ("detail".equals(reportType)) {
            queryTemplate = "SELECT * FROM reports WHERE type='detail' "
                + "AND customer_id = '" + customerId + "' "
                + "ORDER BY ${sort_col} ASC";
        } else {
            resp.sendError(400, "Unknown report type");
            return;
        }

        StringSubstitutor sub = new StringSubstitutor(templateVars);
        String finalQuery = sub.replace(queryTemplate);

        try {
            Connection conn = getConnection();
            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(finalQuery);

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.write("[\n");
            boolean first = true;
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            while (rs.next()) {
                if (!first) out.write(",\n");
                out.write("{");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) out.write(",");
                    out.write("\"" + meta.getColumnName(i) + "\":");
                    out.write("\"" + rs.getString(i) + "\"");
                }
                out.write("}");
                first = false;
            }
            out.write("\n]");
            rs.close();
            stmt.close();
            conn.close();
        } catch (SQLException e) {
            resp.sendError(500, "Query failed");
        }
    }

    private Connection getConnection() throws SQLException {
        String url = System.getenv("JDBC_URL");
        String user = System.getenv("DB_USER");
        String pass = System.getenv("DB_PASS");
        return DriverManager.getConnection(url, user, pass);
    }
}
